    world.particles.push({
      x, y,
      vx: Math.cos(a) * s, vy: Math.sin(a) * s,
      life: 0.5 + world.rng() * 0.3, max: 0.8,
      r: 1.5 + world.rng() * 2,
      color,
    });
  }
}

